import os

# Check existing cache on this server
cache_dir = '/root/autodl-tmp/crm_cache/spatial'
if os.path.exists(cache_dir):
    for f in os.listdir(cache_dir):
        path = os.path.join(cache_dir, f)
        if f.endswith('.pt'):
            d = torch.load(path, map_location='cpu', weights_only=True)
            if hasattr(d, 'shape'):
                print(f'{f}: {d.shape} {d.dtype}')
            else:
                print(f'{f}: type={type(d)}')
        elif f.endswith('.json'):
            import json
            print(f'{f}: {json.load(open(path))}')
else:
    print('No cache dir on this server')
